// Builds the playlist pages from whatever is in playlists/.
//
//   node .github/scripts/build-playlists.js
//
// Each folder of audio files becomes playlists/<folder>/index.html, and
// playlists/index.html lists them all. The pages are plain HTML (Jekyll copies
// them as-is), with the playlist's name in the <title> and og: tags so shared
// links preview properly.
//
// The pre-commit hook (.githooks/pre-commit) runs this and stages the pages.
// The "Playlist pages" check runs it with --check on pull requests, which
// writes nothing and fails if any page is missing or out of date.
//
// Optional per-folder settings in playlists/<folder>/playlist.json:
//   { "title": "Rehearsal Covers" }
const fs = require('fs');
const path = require('path');

const SITE = 'https://discountfireworks.band';
const ROOT = path.join(__dirname, '..', '..', 'playlists');
const CHECK = process.argv.includes('--check');
const MARKER = '<!-- Generated by .github/scripts/build-playlists.js. Edits here get overwritten; see playlists/README.md. -->';

const AUDIO = /\.(mp3|m4a|aac|wav|ogg|oga|opus|flac|webm)$/i;
const IMAGE = /\.(jpe?g|png|gif|webp)$/i;
const byName = (a, b) => a.localeCompare(b, undefined, { numeric: true });

const esc = (s) => String(s).replace(/[&<>"]/g, (c) => `&#${c.charCodeAt(0)};`);
const href = (...parts) => '/' + parts.map(encodeURIComponent).join('/');

function titleFromFolder(name) {
  return name
    .replace(/[-_]+/g, ' ')
    .trim()
    .replace(/\b(lp|ep)\b/gi, (m) => m.toUpperCase())
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function trackTitle(file) {
  return file
    .replace(/\.[^.]+$/, '')          // extension
    .replace(/^\d+[\s._-]+/, '')      // leading track number
    .replace(/_+/g, ' ');
}

function readSettings(dir) {
  const file = path.join(dir, 'playlist.json');
  if (!fs.existsSync(file)) return {};
  try {
    return JSON.parse(fs.readFileSync(file, 'utf8'));
  } catch (err) {
    throw new Error(`Couldn't read ${path.relative(process.cwd(), file)}: ${err.message}`);
  }
}

function page({ title, url, image, type, body }) {
  return `<!DOCTYPE html>
${MARKER}
<html>
<head>
    <title>${esc(title)}</title>
    <meta name="viewport" content="user-scalable=0, initial-scale=1.0">
    <meta property="og:title" content="${esc(title)}">
    <meta property="og:type" content="${type}">
    <meta property="og:url" content="${esc(SITE + url)}">
    <meta property="og:image" content="${esc(SITE + image)}">
    <link rel="stylesheet" href="/css.css">
    <link rel="stylesheet" href="/playlists/player.css">
</head>
<body>
<div class="container">
    <h2><a href="/">Discount Fireworks</a></h2>
    <hr>
${body}
</div>
</body>
</html>
`;
}

// Writes a file only when its contents change, and reports what it did
// (one "wrote <path>" / "removed <path>" line each; the hook reads these).
const changes = [];
function write(file, contents) {
  if (fs.existsSync(file) && fs.readFileSync(file, 'utf8') === contents) return;
  changes.push(`wrote ${path.relative(process.cwd(), file)}`);
  if (!CHECK) fs.writeFileSync(file, contents);
}
function remove(file) {
  changes.push(`removed ${path.relative(process.cwd(), file)}`);
  if (!CHECK) fs.unlinkSync(file);
}
function isGenerated(file) {
  return fs.existsSync(file) && fs.readFileSync(file, 'utf8').includes(MARKER);
}

const playlists = [];
for (const entry of fs.readdirSync(ROOT, { withFileTypes: true })) {
  if (!entry.isDirectory() || /^[._]/.test(entry.name)) continue;
  const folder = entry.name;
  const dir = path.join(ROOT, folder);
  const indexFile = path.join(dir, 'index.html');
  const files = fs.readdirSync(dir).filter((f) => !/^[._]/.test(f)).sort(byName);
  const tracks = files.filter((f) => AUDIO.test(f));

  if (!tracks.length) {
    // Folder emptied out: drop the page we made for it.
    if (isGenerated(indexFile)) remove(indexFile);
    continue;
  }
  if (fs.existsSync(indexFile) && !isGenerated(indexFile)) {
    console.warn(`Skipping ${folder}: it has a hand-made index.html.`);
    continue;
  }

  const settings = readSettings(dir);
  const title = settings.title || titleFromFolder(folder);
  const images = files.filter((f) => IMAGE.test(f));
  const cover = images.find((f) => /^(cover|folder|front)\./i.test(f)) || images[0];
  const url = href('playlists', folder) + '/';

  const body = [
    cover ? `    <img class="cover" src="${esc(href('playlists', folder, cover))}" alt="">` : '',
    `    <h3>${esc(title)}</h3>`,
    `    <audio id="player" controls preload="metadata" controlsList="nodownload noplaybackrate" oncontextmenu="return false"></audio>`,
    `    <div class="controls"><button id="prev" aria-label="Previous track">&#9198;</button><button id="next" aria-label="Next track">&#9197;</button></div>`,
    `    <ol class="tracks" data-album="${esc(title)}">`,
    ...tracks.map((t, i) =>
      `        <li data-src="${esc(href('playlists', folder, t))}"><span class="num">${i + 1}</span><span class="name">${esc(trackTitle(t))}</span></li>`),
    `    </ol>`,
    `    <p><a href="/playlists/">&larr; All playlists</a></p>`,
    `    <script src="/playlists/player.js"></script>`,
  ].filter(Boolean).join('\n');

  write(indexFile, page({
    title: `${title} - Discount Fireworks`,
    url,
    image: cover ? href('playlists', folder, cover) : '/discount-fireworks.jpg',
    type: 'music.playlist',
    body,
  }));
  playlists.push({ folder, title, url });
}

playlists.sort((a, b) => byName(a.title, b.title));
const indexBody = [
  `    <h3>Playlists</h3>`,
  playlists.length
    ? `    <div class="playlists">\n${playlists.map((p) => `        <a href="${esc(p.url)}">${esc(p.title)}</a>`).join('\n')}\n    </div>`
    : `    <p class="empty">No playlists yet.</p>`,
  `    <script>`,
  `    // Old-style links (/playlists/#folder) go to the playlist's own page.`,
  `    var folders = ${JSON.stringify(playlists.map((p) => p.folder))};`,
  `    var name = decodeURIComponent(location.hash.slice(1));`,
  `    if (folders.indexOf(name) >= 0) location.replace('/playlists/' + encodeURIComponent(name) + '/');`,
  `    </script>`,
].join('\n');

write(path.join(ROOT, 'index.html'), page({
  title: 'Discount Fireworks - Playlists',
  url: '/playlists/',
  image: '/discount-fireworks.jpg',
  type: 'website',
  body: indexBody,
}));

if (CHECK && changes.length) {
  console.error('Playlist pages are out of date. Run `node .github/scripts/build-playlists.js` and commit the result:');
  console.error(changes.map((c) => '  ' + c.replace(/^wrote/, 'would write').replace(/^removed/, 'would remove')).join('\n'));
  process.exit(1);
}
if (changes.length) console.log(changes.join('\n'));
else if (!process.argv.includes('--quiet')) console.log('Playlist pages are up to date.');
